<script setup>import{reactive,ref}from'vue';import{api}from'../api';import{IonPage,IonContent,IonButton}from'@ionic/vue';const result=ref(''),f=reactive({type:'VEHICLE_BREAKDOWN',severity:'HIGH',title:'Vehicle problem',description:'',entityId:'DEL-1001',method:'MOBILE'});async function send(){const{data}=await api.post('/incidents',f);result.value=data.rectification}</script><template><ion-page><ion-content><div class="mob-hero"><small>EXCEPTION WORKFLOW</small><h1>Report incident</h1><p>The platform records the event and attempts a safe rectification action.</p></div><div class="scanbox"><label>Incident type</label><select v-model="f.type"><option>VEHICLE_BREAKDOWN</option><option>DRIVER_UNAVAILABLE</option><option>INVENTORY_MISMATCH</option><option>RETURN_GOODS</option><option>DAMAGED_GOODS</option></select><label>Linked delivery / item</label><input v-model="f.entityId"/><label>Description</label><textarea v-model="f.description" placeholder="What happened?"></textarea><ion-button expand="block" color="danger" @click="send">Report incident</ion-button><div v-if="result" class="note"><b>Rectification created:</b><br>{{result}}</div></div></ion-content></ion-page></template>
